/**
 * Codegen: engine catalog → TypeScript modules.
 *
 * Reads `engine/catalog.snapshot.json` (generated by the Rust engine)
 * and produces:
 *   - `src/generated/catalog.ts` — node type definitions + processor metadata
 *   - `src/generated/schemas.ts` — Zod schemas for engine-backed node types
 *   - `src/generated/definitionSchema.ts` — JSON Schema for `.bnto.json` files
 *   - `packages/@bnto/backend/convex/_helpers/nodeTypeLabels.ts` — label map for Convex
 *   - `packages/@bnto/i18n/src/generated/nodes.json` — i18n strings for node types + params
 *
 * The Rust engine is the single source of truth for ALL node metadata.
 * Run via: `task nodes:generate` or `npx tsx scripts/generate-from-catalog.ts`
 */

import { readFileSync, writeFileSync, mkdirSync, rmSync } from "node:fs";
import { resolve, dirname } from "node:path";

// --- Paths ---

const ROOT = resolve(dirname(import.meta.url.replace("file://", "")), "../../../..");
const CATALOG_PATH = resolve(ROOT, "engine/catalog.snapshot.json");
const GENERATED_DIR = resolve(ROOT, "packages/@bnto/nodes/src/generated");
const CATALOG_OUTPUT = resolve(GENERATED_DIR, "catalog.ts");
const SCHEMAS_OUTPUT = resolve(GENERATED_DIR, "schemas.ts");
const DEF_SCHEMA_OUTPUT = resolve(GENERATED_DIR, "definitionSchema.ts");
const DOCS_DIR = resolve(ROOT, "packages/@bnto/nodes/docs");
const CONVEX_LABELS_OUTPUT = resolve(
  ROOT,
  "packages/@bnto/backend/convex/_helpers/nodeTypeLabels.ts",
);
const I18N_STRINGS_OUTPUT = resolve(ROOT, "packages/@bnto/i18n/src/generated/nodes.json");

// Clean up old separate nodeTypes.ts if it exists
const OLD_NODE_TYPES = resolve(GENERATED_DIR, "nodeTypes.ts");

// --- Types matching engine/catalog.snapshot.json schema ---

interface CatalogEnvelope {
  version: string;
  nodeTypes: RawNodeType[];
  processors: RawProcessor[];
  definitionSchema?: Record<string, unknown>;
}

interface RawNodeType {
  name: string;
  label: string;
  description: string;
  category: string;
  isContainer: boolean;
  platforms: string[];
  icon: string;
}

interface RawProcessor {
  nodeType: string;
  name: string;
  description: string;
  category: string;
  accepts: string[];
  platforms: string[];
  parameters: RawParameter[];
  inputCardinality?: string;
}

interface RawParameter {
  name: string;
  label: string;
  description: string;
  paramType: { type: string; options?: string[] };
  default?: unknown;
  constraints?: { min?: number; max?: number; required?: boolean };
  placeholder?: string;
  surfaceable?: boolean;
}

// --- Read catalog ---

const raw = readFileSync(CATALOG_PATH, "utf-8");
const catalog: CatalogEnvelope = JSON.parse(raw);

// --- Helpers ---

function indent(s: string, n: number): string {
  const pad = "  ".repeat(n);
  return s
    .split("\n")
    .map((line) => (line.trim() ? pad + line : line))
    .join("\n");
}

function serializeValue(v: unknown): string {
  if (v === null || v === undefined) return "undefined";
  if (typeof v === "string") return JSON.stringify(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  return JSON.stringify(v);
}

/** Convert kebab-case to camelCase. */
function toCamelCase(s: string): string {
  return s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
}

/** Convert kebab-case to PascalCase. */
function toPascalCase(s: string): string {
  const camel = toCamelCase(s);
  return camel.charAt(0).toUpperCase() + camel.slice(1);
}

// =============================================================================
// Node type generation (catalog.ts)
// =============================================================================

function generateNodeTypeEntry(t: RawNodeType): string {
  const browserCapable = t.platforms.includes("browser");
  return `  ${JSON.stringify(t.name)}: {
    name: ${JSON.stringify(t.name)},
    label: ${JSON.stringify(t.label)},
    description: ${JSON.stringify(t.description)},
    category: ${JSON.stringify(t.category)},
    isContainer: ${t.isContainer},
    browserCapable: ${browserCapable},
    icon: ${JSON.stringify(t.icon)},
  }`;
}

function generateNodeTypesSection(): string {
  const types = catalog.nodeTypes;

  const nodeTypesEntries = types
    .map((t) => `  ${toCamelCase(t.name)}: ${JSON.stringify(t.name)}`)
    .join(",\n");

  const nodeTypeInfoEntries = types.map((t) => generateNodeTypeEntry(t)).join(",\n");

  const categories = [...new Set(types.map((t) => t.category))].sort();
  const categoryUnion = categories.map((c) => `"${c}"`).join(" | ");

  return `// =============================================================================
// Node Types — All ${types.length} registered node types
// =============================================================================

/**
 * All registered node type names.
 * Maps camelCase keys to kebab-case type name strings.
 */
export const NODE_TYPES = {
${nodeTypesEntries},
} as const;

/** Union of all valid node type name strings. */
export type NodeTypeName = (typeof NODE_TYPES)[keyof typeof NODE_TYPES];

/** All node type names as a readonly array. */
export const NODE_TYPE_NAMES: readonly NodeTypeName[] = Object.values(NODE_TYPES) as NodeTypeName[];

/** Node category for grouping in the UI and documentation. */
export type NodeCategory = ${categoryUnion};

/** Metadata describing a node type's behavior and capabilities. */
export interface NodeTypeInfo {
  /** The node type name as used in \`.bnto.json\` definitions. */
  name: NodeTypeName;
  /** Human-readable display label. */
  label: string;
  /** One-sentence description of what the node does. */
  description: string;
  /** Category for grouping. */
  category: NodeCategory;
  /** Whether this node can contain child nodes (group, loop). */
  isContainer: boolean;
  /** Whether this node type is available for browser execution. */
  browserCapable: boolean;
  /** Lucide icon name for visual consumers. */
  icon: string;
}

/**
 * Metadata for all ${types.length} registered node types.
 * Maps node type name → info.
 */
export const NODE_TYPE_INFO: Record<NodeTypeName, NodeTypeInfo> = {
${nodeTypeInfoEntries},
} as const satisfies Record<NodeTypeName, NodeTypeInfo>;`;
}

// =============================================================================
// Processor generation (catalog.ts)
// =============================================================================

function generateParam(p: RawParameter): string {
  const lines: string[] = [];
  lines.push("{");
  lines.push(`  name: ${JSON.stringify(p.name)},`);
  lines.push(`  label: ${JSON.stringify(p.label)},`);
  lines.push(`  description: ${JSON.stringify(p.description)},`);

  if (p.paramType.options) {
    lines.push(`  type: "enum" as const,`);
    lines.push(`  options: ${JSON.stringify(p.paramType.options)} as const,`);
  } else {
    lines.push(`  type: ${JSON.stringify(p.paramType.type)} as const,`);
  }

  if (p.default !== undefined) {
    lines.push(`  default: ${serializeValue(p.default)},`);
  }
  if (p.constraints) {
    const parts: string[] = [];
    if (p.constraints.min !== undefined) parts.push(`min: ${p.constraints.min}`);
    if (p.constraints.max !== undefined) parts.push(`max: ${p.constraints.max}`);
    if (p.constraints.required !== undefined) parts.push(`required: ${p.constraints.required}`);
    lines.push(`  constraints: { ${parts.join(", ")} },`);
  }
  if (p.placeholder !== undefined) {
    lines.push(`  placeholder: ${JSON.stringify(p.placeholder)},`);
  }
  if (p.surfaceable === false) {
    lines.push(`  surfaceable: false,`);
  }
  lines.push("}");
  return lines.join("\n");
}

function generateProcessor(p: RawProcessor): string {
  const params = p.parameters.map((param) => indent(generateParam(param), 2)).join(",\n");
  const cardinality = p.inputCardinality ?? "perFile";
  return `{
  nodeType: ${JSON.stringify(p.nodeType)},
  name: ${JSON.stringify(p.name)},
  description: ${JSON.stringify(p.description)},
  category: ${JSON.stringify(p.category)},
  accepts: ${JSON.stringify(p.accepts)} as const,
  platforms: ${JSON.stringify(p.platforms)} as const,
  parameters: [
${params},
  ],
  inputCardinality: ${JSON.stringify(cardinality)} as const,
}`;
}

function generateProcessorsSection(): string {
  const sorted = [...catalog.processors].sort((a, b) => a.nodeType.localeCompare(b.nodeType));

  const processorsCode = sorted.map((p) => indent(generateProcessor(p), 1)).join(",\n");

  return `// =============================================================================
// Processors — ${sorted.length} per-operation node types
// =============================================================================

export type ParamType = "number" | "string" | "boolean" | "enum" | "object";

export interface ProcessorParam {
  readonly name: string;
  readonly label: string;
  readonly description: string;
  readonly type: ParamType;
  readonly options?: readonly string[];
  readonly default?: unknown;
  readonly constraints?: {
    readonly min?: number;
    readonly max?: number;
    readonly required?: boolean;
  };
  readonly placeholder?: string;
  /** Whether this param is eligible for surfacing in container config panels. Defaults to true. */
  readonly surfaceable?: boolean;
}

export interface ProcessorDef {
  readonly nodeType: string;
  readonly name: string;
  readonly description: string;
  readonly category: string;
  readonly accepts: readonly string[];
  readonly platforms: readonly string[];
  readonly parameters: readonly ProcessorParam[];
  readonly inputCardinality: "perFile" | "batch";
}

export const PROCESSORS: readonly ProcessorDef[] = [
${processorsCode},
] as const;

// --- Lookup helpers ---

/** Map keyed by nodeType for O(1) lookup. */
export const PROCESSOR_MAP = new Map<string, ProcessorDef>(
  PROCESSORS.map((p) => [p.nodeType, p]),
);

/** Get the engine defaults for a node type. */
export function getProcessorDefaults(
  nodeType: string,
): Record<string, unknown> {
  const proc = PROCESSOR_MAP.get(nodeType);
  if (!proc) return {};
  const defaults: Record<string, unknown> = {};
  for (const param of proc.parameters) {
    if (param.default !== undefined) {
      defaults[param.name] = param.default;
    }
  }
  return defaults;
}

/** Get the engine constraints for a specific parameter. */
export function getParamConstraints(
  nodeType: string,
  paramName: string,
): ProcessorParam["constraints"] | undefined {
  const proc = PROCESSOR_MAP.get(nodeType);
  if (!proc) return undefined;
  const param = proc.parameters.find((p) => p.name === paramName);
  return param?.constraints;
}

/** Get the accepted MIME types for a node type. */
export function getProcessorAccepts(
  nodeType: string,
): readonly string[] {
  const proc = PROCESSOR_MAP.get(nodeType);
  return proc?.accepts ?? [];
}`;
}

// =============================================================================
// Zod schema generation (schemas.ts)
// =============================================================================

/**
 * Generate one Zod schema per processor (1:1 mapping).
 * No operation enum — each node type IS an operation.
 */
function generateSchemasFile(): string {
  const sections: string[] = [];

  const sorted = [...catalog.processors].sort((a, b) => a.nodeType.localeCompare(b.nodeType));

  for (const proc of sorted) {
    const nodeType = proc.nodeType;
    const pascalName = toPascalCase(nodeType);

    const zodFields: string[] = [];
    for (const param of proc.parameters) {
      zodFields.push(`  ${generateZodField(param)},`);
    }

    const schemaName = `${toCamelCase(nodeType)}ParamsSchema`;
    const typeName = `${pascalName}Params`;

    sections.push(
      `/** Zod schema for ${nodeType} node parameters (auto-generated from engine). */`,
      `export const ${schemaName} = z.object({`,
      ...zodFields,
      `});`,
      "",
      `/** Inferred TypeScript type for ${nodeType} node parameters. */`,
      `export type ${typeName} = z.infer<typeof ${schemaName}>;`,
      "",
    );

    const uiMetaEntries: string[] = [];
    for (const param of proc.parameters) {
      uiMetaEntries.push(generateNodeParam(param));
    }

    const nodeSchemaName = `${toCamelCase(nodeType)}NodeSchema`;
    sections.push(
      `/** Full schema definition for the ${nodeType} node type (auto-generated from engine). */`,
      `export const ${nodeSchemaName}: NodeSchema = {`,
      `  nodeType: ${JSON.stringify(nodeType)},`,
      `  schemaVersion: 1,`,
      `  schema: ${schemaName},`,
      `  params: {`,
      ...uiMetaEntries,
      `  },`,
      `};`,
      "",
    );
  }

  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * Zod schemas and UI metadata for engine-backed node types.
 * Run \`task nodes:generate\` to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

import { z } from "zod";
import type { NodeSchema } from "../schemas/types";

${sections.join("\n")}`;
}

/** Generate a single Zod field from a RawParameter. */
function generateZodField(param: RawParameter): string {
  const name = param.name;
  let zodChain: string;

  switch (param.paramType.type) {
    case "number": {
      zodChain = "z.number()";
      if (param.constraints?.min !== undefined) {
        zodChain += `.min(${param.constraints.min})`;
      }
      if (param.constraints?.max !== undefined) {
        zodChain += `.max(${param.constraints.max})`;
      }
      break;
    }
    case "string": {
      zodChain = "z.string()";
      break;
    }
    case "boolean": {
      zodChain = "z.boolean()";
      break;
    }
    case "enum": {
      const options = param.paramType.options ?? [];
      zodChain = `z.enum(${JSON.stringify(options)} as const)`;
      break;
    }
    case "object": {
      zodChain = "z.record(z.string())";
      break;
    }
    default: {
      zodChain = "z.unknown()";
    }
  }

  if (param.constraints?.required) {
    if (param.default !== undefined) {
      zodChain += `.default(${serializeValue(param.default)})`;
    }
  } else {
    zodChain += ".optional()";
    if (param.default !== undefined) {
      zodChain += `.default(${serializeValue(param.default)})`;
    }
  }

  return `  ${name}: ${zodChain}`;
}

/** Generate NodeParam entry for a parameter. */
function generateNodeParam(param: RawParameter): string {
  const lines: string[] = [];
  lines.push(`    ${param.name}: {`);
  lines.push(`      label: ${JSON.stringify(param.label)},`);
  lines.push(`      description: ${JSON.stringify(param.description)},`);
  if (param.placeholder !== undefined) {
    lines.push(`      placeholder: ${JSON.stringify(param.placeholder)},`);
  }
  if (param.surfaceable === false) {
    lines.push(`      surfaceable: false,`);
  }
  lines.push(`    },`);
  return lines.join("\n");
}

// =============================================================================
// Definition JSON Schema generation (definitionSchema.ts)
// =============================================================================

function generateDefinitionSchemaFile(): string {
  if (!catalog.definitionSchema) {
    return `/**
 * Definition JSON Schema — NOT AVAILABLE (engine did not include it).
 */
export const DEFINITION_JSON_SCHEMA = null;
`;
  }

  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * JSON Schema (Draft 2020-12) for \`.bnto.json\` definition files.
 * Use this to validate definition files in any language or tool
 * that supports JSON Schema (VS Code, ajv, jsonschema, etc.).
 *
 * Run \`task nodes:generate\` to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

/** JSON Schema for .bnto.json definition files. */
export const DEFINITION_JSON_SCHEMA = ${JSON.stringify(catalog.definitionSchema, null, 2)} as const;
`;
}

// =============================================================================
// Node README generation (docs/*.md)
// =============================================================================

function formatRange(p: RawParameter): string {
  if (p.constraints?.min !== undefined && p.constraints?.max !== undefined) {
    return `${p.constraints.min}–${p.constraints.max}`;
  }
  if (p.constraints?.min !== undefined) return `≥ ${p.constraints.min}`;
  if (p.constraints?.max !== undefined) return `≤ ${p.constraints.max}`;
  return "—";
}

function formatDefault(p: RawParameter): string {
  if (p.default === undefined) return "—";
  return String(p.default);
}

function generateNodeReadme(nodeType: RawNodeType, processor: RawProcessor | undefined): string {
  const lines: string[] = [];
  const platforms = nodeType.platforms.join(", ") || "none";

  lines.push(`# ${nodeType.label} Node`);
  lines.push("");
  lines.push(`> ${nodeType.description}`);
  lines.push("");
  lines.push(
    `**Category:** ${nodeType.category} | **Platforms:** ${platforms} | **Container:** ${nodeType.isContainer ? "yes" : "no"}`,
  );
  lines.push("");

  if (processor) {
    if (processor.accepts.length > 0) {
      lines.push("## Accepts");
      lines.push("");
      for (const mime of processor.accepts) {
        lines.push(`- \`${mime}\``);
      }
      lines.push("");
    }

    if (processor.parameters.length > 0) {
      lines.push("## Parameters");
      lines.push("");
      lines.push("| Parameter | Type | Default | Range | Description |");
      lines.push("|-----------|------|---------|-------|-------------|");

      for (const param of processor.parameters) {
        const type = param.paramType.options ? "enum" : param.paramType.type;
        const range = param.paramType.options
          ? param.paramType.options.join(", ")
          : formatRange(param);
        lines.push(
          `| ${param.name} | ${type} | ${formatDefault(param)} | ${range} | ${param.description} |`,
        );
      }
      lines.push("");
    }

    const exampleParams: Record<string, unknown> = {};
    for (const param of processor.parameters) {
      if (param.default !== undefined) {
        exampleParams[param.name] = param.default;
      } else if (param.constraints?.required) {
        exampleParams[param.name] = param.paramType.options?.[0] ?? `<${param.paramType.type}>`;
      }
    }

    lines.push("## Configuration Example");
    lines.push("");
    lines.push("```json");
    lines.push(`{`);
    lines.push(`  "type": ${JSON.stringify(nodeType.name)},`);
    lines.push(
      `  "parameters": ${JSON.stringify(exampleParams, null, 4)
        .split("\n")
        .map((l, i) => (i === 0 ? l : "  " + l))
        .join("\n")}`,
    );
    lines.push(`}`);
    lines.push("```");
    lines.push("");
  }

  lines.push("---");
  lines.push("");
  lines.push(
    `*Auto-generated from engine catalog v${catalog.version}. Run \`task nodes:generate\` to regenerate.*`,
  );
  lines.push("");

  return lines.join("\n");
}

function generateAllNodeReadmes(): void {
  mkdirSync(DOCS_DIR, { recursive: true });

  const processorByType = new Map<string, RawProcessor>();
  for (const p of catalog.processors) {
    processorByType.set(p.nodeType, p);
  }

  for (const nodeType of catalog.nodeTypes) {
    const processor = processorByType.get(nodeType.name);
    const readme = generateNodeReadme(nodeType, processor);
    const filename = resolve(DOCS_DIR, `${nodeType.name}.md`);
    writeFileSync(filename, readme, "utf-8");
  }

  console.log(`Generated ${catalog.nodeTypes.length} node READMEs in ${DOCS_DIR}`);
}

// =============================================================================
// Convex node type labels (nodeTypeLabels.ts)
// =============================================================================

/** Generate a standalone label map for Convex (can't import from @bnto/nodes). */
function generateConvexLabelsFile(): string {
  const entries = catalog.nodeTypes
    .filter((t) => !t.isContainer && t.category !== "io")
    .map((t) => `  ${JSON.stringify(t.name)}: ${JSON.stringify(t.label)},`)
    .join("\n");

  return `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * Convex can't import from @bnto/nodes (bundling constraint), so this
 * file is generated alongside the main catalog. Run \`task nodes:generate\`
 * to regenerate after engine changes.
 *
 * Engine catalog v${catalog.version}
 */

/** Node type name → display label for processing nodes (excludes I/O and containers). */
export const NODE_TYPE_LABELS: Record<string, string> = {
${entries}
};
`;
}

// =============================================================================
// i18n strings (nodes.json)
// =============================================================================

/** Generate i18n JSON for node type labels, param labels, and categories. */
function generateI18nStringsFile(): string {
  const nodeTypes: Record<string, Record<string, string>> = {};
  const params: Record<string, Record<string, Record<string, string>>> = {};
  const categories: Record<string, string> = {};

  for (const nt of catalog.nodeTypes) {
    const key = toCamelCase(nt.name);
    nodeTypes[key] = { label: nt.label, description: nt.description };
    if (!categories[nt.category]) {
      categories[nt.category] = nt.category.charAt(0).toUpperCase() + nt.category.slice(1);
    }
  }

  for (const proc of catalog.processors) {
    const key = toCamelCase(proc.nodeType);
    if (proc.parameters.length === 0) continue;
    const paramEntries: Record<string, Record<string, string>> = {};
    for (const p of proc.parameters) {
      const entry: Record<string, string> = { label: p.label, description: p.description };
      if (p.placeholder) entry.placeholder = p.placeholder;
      paramEntries[p.name] = entry;
    }
    params[key] = paramEntries;
  }

  const output = {
    _generatedBy: `generate-from-catalog.ts — DO NOT EDIT manually. Engine catalog v${catalog.version}`,
    nodeTypes,
    params,
    categories,
  };

  return JSON.stringify(output, null, 2) + "\n";
}

// =============================================================================
// Assemble and write
// =============================================================================

const catalogOutput = `/**
 * AUTO-GENERATED from engine/catalog.snapshot.json — DO NOT EDIT.
 *
 * Run \`task nodes:generate\` to regenerate after engine changes.
 * Source: engine/crates/bnto-core/src/metadata.rs
 *
 * The Rust engine is the single source of truth for all node metadata.
 * To add or modify a node type, edit \`all_node_types()\` in the engine,
 * then run \`task wasm:build\` → \`task nodes:generate\`.
 *
 * Engine catalog v${catalog.version}
 */

${generateNodeTypesSection()}

${generateProcessorsSection()}
`;

const schemasOutput = generateSchemasFile();
const defSchemaOutput = generateDefinitionSchemaFile();

const convexLabelsOutput = generateConvexLabelsFile();
const i18nStringsOutput = generateI18nStringsFile();

mkdirSync(GENERATED_DIR, { recursive: true });
writeFileSync(CATALOG_OUTPUT, catalogOutput, "utf-8");
writeFileSync(SCHEMAS_OUTPUT, schemasOutput, "utf-8");
writeFileSync(DEF_SCHEMA_OUTPUT, defSchemaOutput, "utf-8");
writeFileSync(CONVEX_LABELS_OUTPUT, convexLabelsOutput, "utf-8");
mkdirSync(dirname(I18N_STRINGS_OUTPUT), { recursive: true });
writeFileSync(I18N_STRINGS_OUTPUT, i18nStringsOutput, "utf-8");
generateAllNodeReadmes();

// Clean up old separate file
try {
  rmSync(OLD_NODE_TYPES);
  console.log(`Removed stale ${OLD_NODE_TYPES}`);
} catch {
  // Doesn't exist, that's fine
}

console.log(`Generated ${CATALOG_OUTPUT}`);
console.log(
  `  ${catalog.nodeTypes.length} node types + ${catalog.processors.length} processors from engine catalog v${catalog.version}`,
);
console.log(`Generated ${SCHEMAS_OUTPUT}`);
console.log(
  `  Zod schemas for ${new Set(catalog.processors.map((p) => p.nodeType)).size} engine-backed node types`,
);
console.log(`Generated ${DEF_SCHEMA_OUTPUT}`);
console.log(
  `  Definition JSON Schema ${catalog.definitionSchema ? "included" : "NOT included (engine didn't provide it)"}`,
);
console.log(`Generated ${CONVEX_LABELS_OUTPUT}`);
console.log(
  `  ${catalog.nodeTypes.filter((t) => !t.isContainer && t.category !== "io").length} processing node labels for Convex`,
);
console.log(`Generated ${I18N_STRINGS_OUTPUT}`);
console.log(
  `  ${catalog.nodeTypes.length} node types + ${catalog.processors.length} processors i18n strings`,
);
